(1425,2919,'Prostheses used to partially or totally replace a human or animal joint. (from UMDNS, 1999)','en',2,'2025-12-19 08:40:35',NULL,NULL,'8589FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1426,2920,'Presence of fluid within the pericardium.','en',2,'2025-12-19 08:40:35',NULL,NULL,'9261FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1427,2921,'Shock due to circulatory insufficiency caused most commonly by gram-negative BACTEREMIA. It is less often the result of the persistent presence of other micro-organisms in the blood (FUNGEMIA, VIREMIA); in rare instances, it is caused by gram-positive organisms, but with different symptomatology.','en',2,'2025-12-19 08:40:35',NULL,NULL,'7981FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1428,2922,'Personal history of sickle cell trait (genetic) without disease.','en',2,'2025-12-19 08:40:35',NULL,NULL,'1469FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
